SELECT CASE WHEN YEAR(p.launch_date) < 2024 THEN 'before_2024' WHEN YEAR(p.launch_date) = 2024 THEN '2024' ELSE 'after_2024' END launch_cohort, ROUND(STDDEV(oi.quantity), 2) stddev_quantity, SUM(oi.quantity * oi.unit_price) revenue FROM order_items oi INNER JOIN products p ON p.id = oi.product_id WHERE p.stock_qty BETWEEN 204 AND 355 GROUP BY CASE WHEN YEAR(p.launch_date) < 2024 THEN 'before_2024' WHEN YEAR(p.launch_date) = 2024 THEN '2024' ELSE 'after_2024' END;
